DROP TABLE IF EXISTS `company_supervision_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `company_supervision_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL,
  `supervision_id` int NOT NULL,
  `supervision_detail_id` int DEFAULT NULL,
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cosmetics',
  `announcement_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'flight_inspection',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_company_supervision_company` (`supervision_id`,`company_id`),
  KEY `idx_company_supervision_company` (`company_id`),
  KEY `idx_company_supervision_supervision` (`supervision_id`),
  KEY `idx_company_supervision_detail` (`supervision_detail_id`),
  KEY `idx_company_supervision_product_type` (`product_type`),
  KEY `idx_company_supervision_announcement_type` (`announcement_type`),
  CONSTRAINT `fk_company_supervision_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_company_supervision_detail` FOREIGN KEY (`supervision_detail_id`) REFERENCES `flight_inspection_detail` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_company_supervision_supervision` FOREIGN KEY (`supervision_id`) REFERENCES `supervisions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
