--
-- Table structure for table `supervisions`
--

DROP TABLE IF EXISTS `supervisions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supervisions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `supervision_date` date DEFAULT NULL,
  `supervision_unit` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `region` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` enum('national','provincial','municipal') COLLATE utf8mb4_unicode_ci NOT NULL,
  `supervision_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cosmetics',
  `announcement_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'flight_inspection',
  `source_detail_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
