DROP TABLE IF EXISTS `unqualified_product_companies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `unqualified_product_companies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `unqualified_product_id` int NOT NULL,
  `company_id` int NOT NULL,
  `role` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `announcement_id` int DEFAULT NULL,
  `announcement_detail_id` int DEFAULT NULL,
  `supervision_id` int DEFAULT NULL,
  `supervision_detail_id` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_upc_product_company_role` (`unqualified_product_id`,`company_id`,`role`),
  KEY `idx_upc_product` (`unqualified_product_id`),
  KEY `idx_upc_company` (`company_id`),
  KEY `idx_upc_role` (`role`),
  KEY `idx_upc_announcement` (`announcement_id`),
  KEY `idx_upc_supervision` (`supervision_id`),
  KEY `idx_upc_company_role` (`company_id`,`role`),
  CONSTRAINT `fk_upc_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_upc_unqualified_product` FOREIGN KEY (`unqualified_product_id`) REFERENCES `unqualified_products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=160002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
