DROP TABLE IF EXISTS `unqualified_product_copy_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `unqualified_product_copy_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `username` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `display_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `copy_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_ids` json NOT NULL,
  `dimension_label` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `range_label` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_upcr_user_id` (`user_id`),
  KEY `idx_upcr_created_at` (`created_at`),
  CONSTRAINT `fk_upcr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
